/* @lc app=leetcode id=1879 lang=kotlin */ class Solution { fun minimumXORSum(nums1: IntArray, nums2: IntArray): Int = nums1.size.let { n -> (0 until (1 shl n)).fold(IntArray(1 shl n) { Int.MAX_VALUE }.also { it[0] = 0 }) { dp, mask -> dp.also { if (it[mask] != Int.MAX_VALUE) Integer.bitCount(mask).let { i -> (0 until n).filter { j -> mask shr j and 1 == 0 }.forEach { j -> it[mask or (1 shl j)] = minOf(it[mask or (1 shl j)], it[mask] + (nums1[i] xor nums2[j])) } } } }[(1 shl n) - 1] } }